<script setup>
import {computed,ref} from 'vue';
import {fdate} from '../../lib/client-info';
import {loadClientDocuments} from '../../lib/client-profile-sections';
import {useClientSectionData} from '../../composables/useClientSectionData';
const props=defineProps({bundle:Object});
const unlocked=ref(false),code=ref(''),codeError=ref(''),category=ref(''),query=ref('');
const {data,loading,error,load}=useClientSectionData(()=>props.bundle,'docs',loadClientDocuments,{immediate:false});
function unlock(){if(code.value!=='90901@90901'){codeError.value='Incorrect code. Please try again.';code.value='';return;}unlocked.value=true;code.value='';load();}
const files=computed(()=>data.value||[]),categories=computed(()=>{const m=new Map();for(const f of files.value)m.set(f.catLabel,(m.get(f.catLabel)||0)+1);return [...m];});
const filtered=computed(()=>files.value.filter(f=>(!category.value||f.catLabel===category.value)&&(!query.value||[f.name,f.doctype,f.docname,f.catLabel].join(' ').toLowerCase().includes(query.value.toLowerCase()))));
</script>
<template><div class="c3-tab-body"><form v-if="!unlocked" id="c3DocumentCode" class="c3-doc-lock" @submit.prevent="unlock"><h3>Documents access</h3><p>Enter the code to view this client’s documents.</p><label>Access code<input v-model="code" type="password" name="code" autocomplete="off" required></label><p role="alert" data-code-error>{{codeError}}</p><button type="submit" class="c3-btn">View documents</button></form><template v-else><p v-if="loading" role="status">Loading client documents…</p><p v-if="error" role="alert">{{error}} <button class="c3-btn" type="button" @click="load(true)">Retry</button></p><template v-if="data"><div v-if="!files.length" class="c3-center c3-empty"><div class="c3-state-ic">📁</div><h3>No documents</h3><p>Before/after photos, consent forms, IDs and payment proofs attached anywhere on this client will collect here.</p></div><template v-else><div class="c3-filters" data-doc-f><button type="button" class="c3-fbtn" :class="{'is-on':!category}" data-f="" @click="category=''">📁 All ({{files.length}})</button><button v-for="[label,count] in categories" :key="label" type="button" class="c3-fbtn" :class="{'is-on':category===label}" :data-f="label" @click="category=label">{{label}} ({{count}})</button><input v-model="query" type="search" class="c3-input c3-doc-search" placeholder="Search file or record" data-doc-q></div><div class="c3-docs" data-doc-grid><article v-for="f in filtered" :key="f.url" class="c3-doc" :data-cat="f.catLabel"><a class="c3-doc-prev" :href="f.url" target="_blank" rel="noopener"><img v-if="f.type==='image'" :src="f.url" :alt="f.name" loading="lazy"><template v-else-if="f.type==='video'"><video :src="f.url+'#t=0.1'" preload="metadata" muted playsinline></video><span class="c3-play">▶</span></template><span v-else class="c3-doc-ic">{{f.type==='pdf'?'📕':'📄'}}</span></a><div class="c3-doc-b"><span class="c3-pill tone-info">{{f.catLabel}}</span><b :title="f.name">{{f.name}}</b><small>{{f.doctype}} {{f.docname}}, {{fdate(f.modified)}}</small></div><div class="c3-doc-act"><a :href="f.url" target="_blank" rel="noopener">👁 View</a><a :href="f.url" download>⬇ Download</a></div></article></div><div v-if="!filtered.length" class="c3-empty-sm" data-doc-none>No files match.</div></template></template></template></div></template>
